/* OK_To_Zoom */
#define SCRZ (*(int *)&D_000970E4)
int OK_To_Zoom(void) {
    int old, r;
    struct V3 t;
    old = SCRZ;
    t.x = car_data[0].x;
    t.y = -car_data[0].y;
    t.z = car_data[0].z;
    SCRZ = (dist(&camera_position, &t) >> 4) + 0x100;
    if (SCRZ > 0x320) SCRZ = 0x320;
    if (SCRZ < 0x100) SCRZ = 0x100;
    r = CameraCollisionCheck() == 0;
    SCRZ = old;
    return r;
}
#undef SCRZ
